   540  static int
   541  cmp_func (const unsigned char *p1, const unsigned char *p2, ExifByteOrder o)
   542  {
   543          ExifShort tag1 = exif_get_short (p1, o);
   544          ExifShort tag2 = exif_get_short (p2, o);
   545
   546          return (tag1 < tag2) ? -1 : (tag1 > tag2) ? 1 : 0;
   547  }
