   226                                                 EXIF_LOG_CODE_DEBUG, "ExifData",
   227                                                 "MakerNote found (%02x %02x %02x %02x "
   228                                                 "%02x %02x %02x...).",
   229                                                 entry->data[0], entry->data[1], entry->data[2],
   230                                                 entry->data[3], entry->data[4], entry->data[5],
   231                                                 entry->data[6]);
   232                  }
   233                  data->priv->offset_mnote = doff;
